contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(uint _val) public {
        // Record MinSum before the deciding call. On a fresh contract this is 0.
        uint beforeMinSum = c.MinSum(); if (__ESBMC_reverted()) return;

        // Deciding call: Initialized() must never revert on a fresh contract.
        bool initializedReverted;
        c.Initialized(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            initializedReverted = true;
        } else {
            initializedReverted = false;
        }

        // Record MinSum after Initialized().
        uint afterMinSum = c.MinSum(); if (__ESBMC_reverted()) return;

        // General rule: Initialized() succeeds (does not revert) and does not change MinSum,
        // regardless of the input _val.
        assert(!initializedReverted && afterMinSum == beforeMinSum);
    }
}

